INSERT INTO courses (code, title, units, mode, description, requisite_text, convener, class_start, class_end, enrol_by, census, source_url) VALUES
('COMP6240', 'Relational Databases', 6, 'In Person', 'This course is an introduction to relational databases and the general skills for designing and using them. The topics include the relational data model, SQL, entity-relationship model,functional dependencies,(de-)normalisation, relational algebra, query processing and optimisation, database transactions and security. To deepen the understanding of relational databases, the current industry development of database systems such as NoSQL databases will be introduced at the end of this course.', 'You are not able to enrol in this course if you have successfully completed COMP2400. Incompatible with COMP7240.', NULL, '2027-02-22', '2027-05-28', '2027-03-01', '2027-03-31', 'https://programsandcourses.anu.edu.au/2027/course/COMP6240'),
('COMP6242', 'Deep Learning', 6, 'In Person', 'The course covers the theory and practice of deep learning. Students will learn the foundational mathematics behind deep learning and explore topics such as multi-layer perceptrons (MLPs), back-propagation and automatic differentiation, convolutional neural networks (CNNs), recurrent neural networks (RNNs), transformers, generative models, and the role of data in training models. These techniques play a crucial role in modern AI systems, including image and video understanding, natural language processing, generative AI, robotics, medicine and scientific discovery. The various practical assessments will enhance student''s understanding and intuition of deep learning and its application.', 'To enrol in this course you must have successfully completed: (COMP3670 or COMP6670 or COMP8410) AND (COMP1110 or COMP6710 or COMP7710 or COMP1730 or COMP6730).', NULL, '2027-02-22', '2027-05-28', '2027-03-01', '2027-03-31', 'https://programsandcourses.anu.edu.au/2027/course/COMP6242'),
('COMP6262', 'Logic', 6, 'In Person', 'Formal logic is the fundamental mathematics of computer science. Its impact ranges from the design of programming languages and hardware, to the specification and verification of critical software, to artificial intelligence systems that can reason. This course introduces propositional and predicate logic. We discuss how to reason within these logics, how to reason about their properties and limitations, and how to use them to model situations of interest in both natural language and computer science applications. We explore how computational thinking can help us solve logic problems.', 'You are not able to enrol in this course if you have previously completed PHIL2080 or COMP2620.', NULL, '2027-02-22', '2027-05-28', '2027-03-01', '2027-03-31', 'https://programsandcourses.anu.edu.au/2027/course/COMP6262'),
('COMP6300', 'Computer Architecture', 6, 'In Person', 'This course is a rigorous introduction to the design of digital circuits and computer architecture. It provides technical foundations for how a computer system is built from the bottom up and how the high-level programming languages you learn in other courses are translated into simple instructions the computer executes. The course introduces the different abstraction layers necessary to make a computer system work, and a key focus is the connection between hardware and software.
